// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract CallerProxy {
    address public target;
    constructor(address _target) { target = _target; }
    function callOwner() external returns (bytes memory) {
        (bool ok, bytes memory ret) = target.call(abi.encodeWithSignature("owner()"));
        require(ok, "call failed");
        return ret;
    }
}

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        CallerProxy proxy = new CallerProxy(address(c));

        vm.deal(caller, 1 ether);

        vm.prank(caller);
        bytes memory ret = proxy.callOwner();

        address returned = abi.decode(ret, (address));

        assertTrue(returned == address(this));
    }
}
